#!/usr/bin/env python3
#=========================================================================
# build_tag_check
#=========================================================================
# Verifier for the BUILD_TAG = 'profiling' instrumentation across the
# 10 modules changed for the profiling sandbox (3 in lab1_imul, 7 in
# lab2_proc).
#
# pymtl3 / pymtl are NOT installed in this environment, so minimal stub
# modules are registered in sys.modules (with dynamic module-level
# __getattr__ and __all__ entries) before importing. Only what executes
# at import time needs to work: class bases (Component,
# VerilogPlaceholder) and the from-imports themselves. Method bodies are
# never executed.
#
# Run from the sim directory:  python3 build_tag_check.py
# Exits 0 if every module has BUILD_TAG == 'profiling'.

import importlib.util
import os
import sys
import types

HERE = os.path.dirname( os.path.abspath( __file__ ) )

#=========================================================================
# Stub machinery for pymtl3 / pymtl / XcelMsg
#=========================================================================

# Any attribute on a stub object or stub class resolves to a fresh stub
# class, so that stubs can be used as base classes (e.g. Component,
# VerilogPlaceholder), called, indexed, and attribute-chained.

class _StubMeta( type ):

  def __getattr__( cls, name ):
    if name.startswith( '__' ):
      raise AttributeError( name )
    return new_stub_class( name )

  def __call__( cls, *args, **kwargs ):
    return _StubObject()

class _StubObject( object ):

  def __getattr__( self, name ):
    if name.startswith( '__' ):
      raise AttributeError( name )
    return new_stub_class( name )

  def __call__( self, *args, **kwargs ):
    return _StubObject()

  def __getitem__( self, key ):
    return _StubObject()

def new_stub_class( name ):
  return _StubMeta( 'Stub_' + name, ( _StubObject, ), {} )

def register_stub_module( name, all_names=() ):
  mod = types.ModuleType( name )
  mod.__path__  = []
